<?php
require_once __DIR__.'/../includes/auth_check.php';require_once __DIR__.'/../config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('../dashboard.php');verify_csrf();$uid=current_user_id();$pid=(int)($_POST['product_id']??0);$qty=(int)($_POST['jumlah']??0);$type=($_POST['jenis']??'')==='out'?'keluar':'masuk';$date=str_replace('T',' ',$_POST['tanggal']??date('Y-m-d H:i'));$note=trim($_POST['keterangan']??'');
if($pid<1||$qty<1){flash('error','Pilih barang dan masukkan jumlah yang valid.');redirect('create.php?type='.($type==='masuk'?'in':'out'));}
try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT id,stok FROM products WHERE id=? AND user_id=? FOR UPDATE');$s->execute([$pid,$uid]);$p=$s->fetch();if(!$p)throw new RuntimeException('Barang tidak ditemukan.');$before=(int)$p['stok'];if($type==='keluar'&&$qty>$before)throw new RuntimeException('Stok tidak mencukupi. Stok tersedia: '.$before.'.');$after=$type==='masuk'?$before+$qty:$before-$qty;
$u=$pdo->prepare('UPDATE products SET stok=? WHERE id=? AND user_id=?');$u->execute([$after,$pid,$uid]);$t=$pdo->prepare('INSERT INTO stock_transactions(user_id,product_id,jenis,jumlah,stok_sebelum,stok_sesudah,keterangan,created_at) VALUES(?,?,?,?,?,?,?,?)');$t->execute([$uid,$pid,$type,$qty,$before,$after,$note,$date]);$pdo->commit();flash('success','Transaksi barang '.($type==='masuk'?'masuk':'keluar').' berhasil disimpan.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof RuntimeException?$e->getMessage():'Transaksi gagal disimpan.');}
redirect('../history/index.php');
